import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  status: 'active' | 'inactive' | 'suspended' | string;
}

export class ToiAccessRevokedError extends Error {
  status = 404;
  code = 'PROJECT_NOT_FOUND';
  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

export async function listRecords(reason: string): Promise<{ items: Customer[] }> {
  const response = await toiFetch('customers', '/customers', { reason });
  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore
    }

    if (response.status === 404) {
      if (errorData?.code === 'PROJECT_NOT_FOUND' || errorData?.error === 'PROJECT_NOT_FOUND') {
        throw new ToiAccessRevokedError();
      }
      // Resource 404 errors with a different code may show no results
      return { items: [] };
    }

    const err: any = new Error(errorData?.message || `Request failed with status ${response.status}`);
    err.status = response.status;
    err.code = errorData?.code;
    throw err;
  }
  return response.json();
}

export async function getRecord(id: string, reason: string): Promise<Customer> {
  const response = await toiFetch('customers', '/customers/' + encodeURIComponent(id), { reason });
  return response.json();
}

export async function updateStatus(id: string, status: 'active' | 'inactive' | 'suspended', reason: string) {
  const response = await toiFetch('customers', '/customers/' + encodeURIComponent(id), {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status })
  });
  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listRecords, Customer } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [accessRevoked, setAccessRevoked] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      return;
    }

    setLoading(true);
    setErrorMessage(null);
    setAccessRevoked(false);

    try {
      const result = await listRecords(trimmedReason);
      const items = Array.isArray(result) ? result : (Array.isArray(result?.items) ? result.items : []);
      setCustomers(items);
      setHasSearched(true);
    } catch (err: any) {
      const isRevoked =
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.message?.includes('PROJECT_NOT_FOUND') ||
        err?.message?.includes('이 프로젝트에 접근할 수 없어요');

      if (isRevoked) {
        setAccessRevoked(true);
        setCustomers([]);
        setHasSearched(false);
      } else if (err?.status === 404) {
        // Resource 404 error with a different code may show no results
        setCustomers([]);
        setHasSearched(true);
      } else {
        setErrorMessage(err?.message || '고객 목록을 조회하는 중 오류가 발생했습니다.');
        setCustomers([]);
        setHasSearched(true);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ padding: '32px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: '0 0 8px 0', color: '#1e293b' }}>고객 목록</h1>
        <p style={{ margin: 0, color: '#64748b', fontSize: '14px' }}>고객 정보를 조회합니다.</p>
      </header>

      <section style={{ marginBottom: '24px', padding: '20px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            if (isReasonValid && !loading) {
              handleSearch();
            }
          }}
        >
          <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div style={{ flex: '1', minWidth: '280px' }}>
              <TextField
                label="조회 사유"
                placeholder="조회 사유를 5자 이상 입력하세요"
                value={reason}
                onChange={(e: any) => {
                  const val = e && typeof e === 'object' && 'target' in e ? e.target.value : String(e ?? '');
                  setReason(val);
                }}
              />
            </div>
            <div>
              <Button
                type="button"
                onClick={handleSearch}
                disabled={!isReasonValid || loading}
              >
                조회
              </Button>
            </div>
          </div>
          {reason.length > 0 && !isReasonValid && (
            <p style={{ margin: '8px 0 0 0', fontSize: '13px', color: '#dc2626' }}>
              조회 사유를 5자 이상 입력해 주세요. (현재 {reason.trim().length}자)
            </p>
          )}
        </form>
      </section>

      {accessRevoked && (
        <div
          role="alert"
          style={{
            padding: '16px 20px',
            backgroundColor: '#fef2f2',
            border: '1px solid #fca5a5',
            borderRadius: '8px',
            color: '#991b1b',
            fontSize: '14px',
            fontWeight: 500,
            lineHeight: '1.5'
          }}
        >
          이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요
        </div>
      )}

      {!accessRevoked && errorMessage && (
        <div
          role="alert"
          style={{
            padding: '16px 20px',
            backgroundColor: '#fffbeb',
            border: '1px solid #fde68a',
            borderRadius: '8px',
            color: '#92400e',
            fontSize: '14px',
            marginBottom: '16px'
          }}
        >
          {errorMessage}
        </div>
      )}

      {!accessRevoked && loading && (
        <div style={{ textAlign: 'center', padding: '40px', color: '#64748b' }}>
          고객 목록을 조회하고 있습니다...
        </div>
      )}

      {!accessRevoked && !loading && !hasSearched && !errorMessage && (
        <div style={{ textAlign: 'center', padding: '48px 16px', color: '#94a3b8', border: '1px dashed #cbd5e1', borderRadius: '8px' }}>
          조회 사유를 5자 이상 입력하고 [조회] 버튼을 눌러주세요.
        </div>
      )}

      {!accessRevoked && !loading && hasSearched && (
        <section>
          <Table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ backgroundColor: '#f1f5f9', borderBottom: '2px solid #cbd5e1' }}>
                <th scope="col" style={{ padding: '12px 16px', fontWeight: 600 }}>id</th>
                <th scope="col" style={{ padding: '12px 16px', fontWeight: 600 }}>name</th>
                <th scope="col" style={{ padding: '12px 16px', fontWeight: 600 }}>phone</th>
                <th scope="col" style={{ padding: '12px 16px', fontWeight: 600 }}>status</th>
              </tr>
            </thead>
            <tbody>
              {customers.length === 0 ? (
                <tr>
                  <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#64748b' }}>
                    조회된 고객 데이터가 없습니다.
                  </td>
                </tr>
              ) : (
                customers.map((customer) => (
                  <tr key={customer.id} style={{ borderBottom: '1px solid #e2e8f0' }}>
                    <td style={{ padding: '12px 16px' }}>{String(customer.id)}</td>
                    <td style={{ padding: '12px 16px' }}>{customer.name}</td>
                    <td style={{ padding: '12px 16px' }}>{customer.phone}</td>
                    <td style={{ padding: '12px 16px' }}>
                      <Badge>{customer.status}</Badge>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </Table>
        </section>
      )}
    </main>
  );
}

