import { useState } from 'react';
import { Button, TextField, Badge } from '@toi/tds';
import { getRecord, Customer } from './api';

export default function App() {
  const [reason, setReason] = useState('고객 상세 정보 확인');
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const customerId = 'C001';

  const handleReasonChange = (e: any) => {
    const val = typeof e === 'string' ? e : (e?.target?.value ?? '');
    setReason(val);
  };

  const handleSearch = async () => {
    if (reason.trim().length < 5) {
      setError('조회 사유를 5자 이상 입력하세요.');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const data = await getRecord(customerId, reason.trim());
      if ((data as any)?.code === 'PROJECT_NOT_FOUND') {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setCustomer(null);
      } else {
        setCustomer(data);
      }
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.message?.includes('PROJECT_NOT_FOUND')
      ) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setCustomer(null);
      } else if (err?.status === 404) {
        setError('조회 결과가 없습니다.');
        setCustomer(null);
      } else {
        setError(err?.message || '조회 중 오류가 발생했습니다.');
        setCustomer(null);
      }
    } finally {
      setLoading(false);
    }
  };

  const isReasonValid = reason.trim().length >= 5;

  return (
    <main style={{ maxWidth: 640, margin: '40px auto', padding: '0 20px', fontFamily: 'system-ui, -apple-system, sans-serif', color: '#1a202c' }}>
      <header style={{ marginBottom: 24, borderBottom: '1px solid #e2e8f0', paddingBottom: 16 }}>
        <h1 style={{ fontSize: 24, fontWeight: 700, margin: '0 0 8px 0' }}>고객 C001 상세 화면</h1>
        <p style={{ margin: 0, color: '#718096', fontSize: 14 }}>고객 C001의 상세 정보를 조회합니다.</p>
      </header>

      <div style={{ backgroundColor: '#f7fafc', border: '1px solid #edf2f7', borderRadius: 8, padding: 20, marginBottom: 24 }}>
        <div style={{ marginBottom: 16 }}>
          <TextField
            label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={handleReasonChange}
          />
          {!isReasonValid && reason.length > 0 && (
            <p style={{ color: '#e53e3e', fontSize: 13, marginTop: 4, margin: '4px 0 0 0' }}>
              조회 사유를 5자 이상 입력하세요.
            </p>
          )}
        </div>

        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
          <Button onClick={handleSearch} disabled={loading || !isReasonValid}>
            조회
          </Button>
        </div>
      </div>

      {error && (
        <div
          role="alert"
          style={{
            marginBottom: 24,
            padding: 14,
            borderRadius: 6,
            backgroundColor: '#fff5f5',
            border: '1px solid #feb2b2',
            color: '#c53030',
            fontSize: 14,
          }}
        >
          {error}
        </div>
      )}

      {customer && (
        <section
          aria-label="고객 상세 정보"
          style={{
            border: '1px solid #e2e8f0',
            borderRadius: 8,
            padding: 24,
            backgroundColor: '#ffffff',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
          }}
        >
          <h2 style={{ fontSize: 18, fontWeight: 600, margin: '0 0 16px 0', borderBottom: '1px solid #edf2f7', paddingBottom: 8 }}>
            고객 정보
          </h2>
          <div style={{ display: 'grid', gridTemplateColumns: '100px 1fr', rowGap: 14, columnGap: 12, alignItems: 'center' }}>
            <div style={{ fontWeight: 600, color: '#4a5568' }}>
              <span>id</span>
            </div>
            <div data-testid="field-id">
              {typeof customer.id === 'number' ? String(customer.id) : customer.id}
            </div>

            <div style={{ fontWeight: 600, color: '#4a5568' }}>
              <span>name</span>
            </div>
            <div data-testid="field-name">
              {typeof customer.name === 'number' ? String(customer.name) : customer.name}
            </div>

            <div style={{ fontWeight: 600, color: '#4a5568' }}>
              <span>phone</span>
            </div>
            <div data-testid="field-phone">
              {typeof customer.phone === 'number' ? String(customer.phone) : customer.phone}
            </div>

            <div style={{ fontWeight: 600, color: '#4a5568' }}>
              <span>status</span>
            </div>
            <div data-testid="field-status" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <Badge>{typeof customer.status === 'number' ? String(customer.status) : customer.status}</Badge>
              <span>{typeof customer.status === 'number' ? String(customer.status) : customer.status}</span>
            </div>
          </div>
        </section>
      )}
    </main>
  );
}

