import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface OrderItem {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  createdAt: string;
  note?: string;
}

export interface ListOrdersResponse {
  items: OrderItem[];
}

export async function fetchOrders(reason: string): Promise<OrderItem[]> {
  const response = await toiFetch('orders', '/orders', { reason });

  if (!response.ok) {
    let errBody: any = null;
    try {
      errBody = await response.json();
    } catch {
      // ignore
    }

    const code = errBody?.code || errBody?.error?.code;

    if (response.status === 404 && code === 'PROJECT_NOT_FOUND') {
      const error: any = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      error.name = 'ToiAccessRevokedError';
      error.status = 404;
      error.code = 'PROJECT_NOT_FOUND';
      throw error;
    }

    if (response.status === 404) {
      // Resource 404 with a different code may show no results
      return [];
    }

    const error: any = new Error(errBody?.message || `요청 실패 (${response.status})`);
    error.status = response.status;
    error.code = code;
    throw error;
  }

  try {
    const data = await response.json();
    return data?.items || [];
  } catch {
    return [];
  }
}

export const listOrders = fetchOrders;
export const listRecords = fetchOrders;

import React, { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { fetchOrders, OrderItem } from './api';

function isAccessRevokedError(err: any): boolean {
  if (!err) return false;
  if (err.name === 'ToiAccessRevokedError') return true;
  if (err.code === 'PROJECT_NOT_FOUND') return true;
  if (err.status === 404 && (err.code === 'PROJECT_NOT_FOUND' || err.data?.code === 'PROJECT_NOT_FOUND')) return true;
  if (typeof err.message === 'string' && (err.message.includes('PROJECT_NOT_FOUND') || err.message.includes('이 프로젝트에 접근할 수 없어요'))) return true;
  return false;
}

export default function App() {
  const [reason, setReason] = useState('주문 목록 조회');
  const [orders, setOrders] = useState<OrderItem[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid || loading) {
      return;
    }

    setLoading(true);
    setErrorMessage(null);

    try {
      const items = await fetchOrders(reason.trim());
      setOrders(items);
      setHasSearched(true);
    } catch (err: any) {
      if (isAccessRevokedError(err)) {
        setErrorMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setOrders(null);
      } else if (err?.status === 404) {
        setOrders([]);
        setHasSearched(true);
      } else {
        setErrorMessage(err?.message || '주문 목록을 불러오지 못했습니다.');
        setOrders(null);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <main style={{ maxWidth: '1000px', margin: '0 auto', padding: '32px 16px', fontFamily: 'system-ui, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700, margin: '0 0 8px 0', color: '#111827' }}>주문 목록</h1>
        <p style={{ margin: 0, color: '#6b7280', fontSize: '14px' }}>주문 내역을 조회하고 관리할 수 있습니다.</p>
      </header>

      <section
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          padding: '20px',
          backgroundColor: '#ffffff',
          borderRadius: '12px',
          border: '1px solid #e5e7eb',
          marginBottom: '24px',
        }}
      >
        <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-end', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 300px' }}>
            <TextField
              label="조회 사유"
              placeholder="조회 사유를 5자 이상 입력하세요"
              value={reason}
              onChange={(e: any) => setReason(typeof e === 'string' ? e : e?.target?.value ?? '')}
              onKeyDown={handleKeyDown}
            />
          </div>
          <Button onClick={handleSearch} disabled={!isReasonValid || loading}>
            조회
          </Button>
        </div>
        {!isReasonValid && (
          <p role="alert" style={{ margin: '4px 0 0', fontSize: '13px', color: '#ef4444' }}>
            조회 사유를 5자 이상 입력해주세요.
          </p>
        )}
      </section>

      {errorMessage && (
        <div
          role="alert"
          style={{
            padding: '16px',
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            borderRadius: '8px',
            color: '#dc2626',
            marginBottom: '24px',
            fontSize: '14px',
            fontWeight: 500,
          }}
        >
          {errorMessage}
        </div>
      )}

      {loading && (
        <div style={{ textAlign: 'center', padding: '32px', color: '#6b7280' }}>
          주문 목록을 불러오는 중...
        </div>
      )}

      {!loading && !errorMessage && hasSearched && orders && (
        <div style={{ backgroundColor: '#ffffff', borderRadius: '12px', border: '1px solid #e5e7eb', overflow: 'hidden' }}>
          <div style={{ overflowX: 'auto' }}>
            <Table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '14px' }}>
              <thead>
                <tr style={{ backgroundColor: '#f9fafb', borderBottom: '1px solid #e5e7eb', color: '#374151' }}>
                  <th style={{ padding: '12px 16px', fontWeight: 600 }}>id</th>
                  <th style={{ padding: '12px 16px', fontWeight: 600 }}>customerId</th>
                  <th style={{ padding: '12px 16px', fontWeight: 600 }}>amount</th>
                  <th style={{ padding: '12px 16px', fontWeight: 600 }}>status</th>
                  <th style={{ padding: '12px 16px', fontWeight: 600 }}>createdAt</th>
                </tr>
              </thead>
              <tbody>
                {orders.length > 0 ? (
                  orders.map((order) => (
                    <tr key={order.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
                      <td style={{ padding: '12px 16px', color: '#111827' }}>{order.id}</td>
                      <td style={{ padding: '12px 16px', color: '#4b5563' }}>{order.customerId}</td>
                      <td style={{ padding: '12px 16px', color: '#111827' }}>{order.amount}</td>
                      <td style={{ padding: '12px 16px' }}>
                        <Badge>{order.status}</Badge>
                      </td>
                      <td style={{ padding: '12px 16px', color: '#6b7280' }}>{order.createdAt}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={5} style={{ padding: '32px', textAlign: 'center', color: '#6b7280' }}>
                      조회 결과가 없습니다.
                    </td>
                  </tr>
                )}
              </tbody>
            </Table>
          </div>
        </div>
      )}

      {!loading && !errorMessage && !hasSearched && (
        <div style={{ textAlign: 'center', padding: '48px 16px', color: '#9ca3af', backgroundColor: '#ffffff', borderRadius: '12px', border: '1px dashed #e5e7eb' }}>
          조회 사유를 확인한 후 조회 버튼을 눌러주세요.
        </div>
      )}
    </main>
  );
}

