// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId?: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export interface ListOrdersParams {
  status?: string;
  sort?: string;
}

export async function listOrders(params: ListOrdersParams, reason: string): Promise<{ items: Order[] }> {
  const searchParams = new URLSearchParams();
  if (params.status) {
    searchParams.set('status', params.status);
  }
  if (params.sort) {
    searchParams.set('sort', params.sort);
  }

  const queryString = searchParams.toString();
  const path = queryString ? `/orders?${queryString}` : '/orders';

  const response = await toiFetch('orders', path, { reason });
  if (!response.ok) {
    const errorBody = await response.json().catch(() => null);
    const error = new Error(errorBody?.message || `Request failed with status ${response.status}`);
    (error as any).status = response.status;
    (error as any).code = errorBody?.code;
    throw error;
  }

  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listOrders, type Order } from './api';

function isAccessRevokedError(err: unknown): boolean {
  if (!err) return false;
  const anyErr = err as { name?: string; code?: string; status?: number; message?: string };
  if (anyErr.name === 'ToiAccessRevokedError') return true;
  if (anyErr.code === 'PROJECT_NOT_FOUND') return true;
  if (anyErr.status === 404 && anyErr.code === 'PROJECT_NOT_FOUND') return true;
  if (typeof anyErr.message === 'string' && anyErr.message.includes('PROJECT_NOT_FOUND')) return true;
  return false;
}

export default function App() {
  const [status, setStatus] = useState('paid');
  const [reason, setReason] = useState('주문 목록 조회');
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid || isLoading) return;

    setIsLoading(true);
    setError(null);

    try {
      const data = await listOrders(
        {
          status: status.trim() ? status.trim() : undefined,
          sort: 'amount_desc',
        },
        reason.trim()
      );

      const items = Array.isArray(data) ? data : (data?.items ?? []);
      setOrders(items);
      setHasSearched(true);
    } catch (err: unknown) {
      if (isAccessRevokedError(err)) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setOrders([]);
      } else if ((err as { status?: number })?.status === 404) {
        // Resource 404 with different code shows no results
        setOrders([]);
        setHasSearched(true);
      } else {
        const anyErr = err as { message?: string };
        setError(anyErr.message || '주문 목록을 불러오는 중 오류가 발생했습니다.');
        setOrders([]);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '1080px', margin: '0 auto', padding: '32px 20px', fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif' }}>
      <header style={{ marginBottom: '28px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: '700', color: '#191f28', margin: '0 0 8px 0' }}>주문 목록</h1>
        <p style={{ fontSize: '14px', color: '#6b7684', margin: 0 }}>
          주문 상태 필터와 정렬 기준(amount 내림차순)으로 주문을 조회합니다.
        </p>
      </header>

      <section style={{ backgroundColor: '#ffffff', border: '1px solid #e5e8eb', borderRadius: '12px', padding: '24px', marginBottom: '24px' }}>
        <div style={{ display: 'flex', gap: '16px', alignItems: 'flex-start', flexWrap: 'wrap' }}>
          <div style={{ minWidth: '180px' }}>
            <TextField
              label="status"
              id="status"
              name="status"
              value={status}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setStatus(e.target.value)}
              placeholder="paid"
            />
          </div>

          <div style={{ flex: 1, minWidth: '280px' }}>
            <TextField
              label="조회 사유"
              id="reason"
              name="reason"
              value={reason}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setReason(e.target.value)}
              placeholder="조회 사유를 5자 이상 입력하세요"
            />
            {reason.length > 0 && !isReasonValid && (
              <p style={{ color: '#f04452', fontSize: '12px', margin: '4px 0 0 0' }}>
                조회 사유는 최소 5자 이상 입력해야 합니다.
              </p>
            )}
          </div>

          <div style={{ paddingTop: '28px' }}>
            <Button
              onClick={handleSearch}
              disabled={!isReasonValid || isLoading}
            >
              {isLoading ? '조회 중...' : '조회'}
            </Button>
          </div>
        </div>
      </section>

      {error && (
        <div
          role="alert"
          style={{
            padding: '16px',
            backgroundColor: '#fee2e2',
            border: '1px solid #fca5a5',
            borderRadius: '8px',
            color: '#b91c1c',
            marginBottom: '24px',
            fontSize: '14px',
          }}
        >
          {error}
        </div>
      )}

      {hasSearched && !error && (
        <section style={{ backgroundColor: '#ffffff', border: '1px solid #e5e8eb', borderRadius: '12px', overflow: 'hidden' }}>
          {orders.length === 0 ? (
            <div style={{ padding: '48px 16px', textAlign: 'center', color: '#8b95a1', fontSize: '15px' }}>
              조회 결과가 없습니다.
            </div>
          ) : (
            <Table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ backgroundColor: '#f9fafb', borderBottom: '1px solid #e5e8eb', textAlign: 'left' }}>
                  <th style={{ padding: '14px 16px', fontSize: '13px', fontWeight: '600', color: '#4e5968' }}>id</th>
                  <th style={{ padding: '14px 16px', fontSize: '13px', fontWeight: '600', color: '#4e5968' }}>amount</th>
                  <th style={{ padding: '14px 16px', fontSize: '13px', fontWeight: '600', color: '#4e5968' }}>status</th>
                  <th style={{ padding: '14px 16px', fontSize: '13px', fontWeight: '600', color: '#4e5968' }}>customerId</th>
                  <th style={{ padding: '14px 16px', fontSize: '13px', fontWeight: '600', color: '#4e5968' }}>createdAt</th>
                </tr>
              </thead>
              <tbody>
                {orders.map((order) => (
                  <tr key={order.id} style={{ borderBottom: '1px solid #f2f4f6' }}>
                    <td style={{ padding: '14px 16px', fontSize: '14px', color: '#191f28' }}>{order.id}</td>
                    <td style={{ padding: '14px 16px', fontSize: '14px', color: '#191f28' }}>{order.amount}</td>
                    <td style={{ padding: '14px 16px', fontSize: '14px', color: '#191f28' }}>
                      <Badge>{order.status}</Badge>
                    </td>
                    <td style={{ padding: '14px 16px', fontSize: '14px', color: '#4e5968' }}>{order.customerId || '-'}</td>
                    <td style={{ padding: '14px 16px', fontSize: '14px', color: '#4e5968' }}>{order.createdAt || '-'}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          )}
        </section>
      )}
    </main>
  );
}

