type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) {
  throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
}
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export async function getOrder(id: string, reason: string): Promise<Order> {
  const response = await toiFetch('orders', `/orders/${encodeURIComponent(id)}`, { reason });
  if (!response.ok) {
    let errorData: any = {};
    try {
      errorData = await response.json();
    } catch {
      // ignore
    }
    const error: any = new Error(errorData.message || `Request failed with status ${response.status}`);
    error.status = response.status;
    error.code = errorData.code;
    throw error;
  }
  return response.json();
}

