  const [orderId, setOrderId] = useState('O001');
  const [reason, setReason] = useState('주문 상세 내역 확인');
  const [order, setOrder] = useState<Order | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [revokedError, setRevokedError] = useState<string | null>(null);
  const [notFoundError, setNotFoundError] = useState<string | null>(null);
  const [generalError, setGeneralError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid) return;

    setIsLoading(true);
    setRevokedError(null);
    setNotFoundError(null);
    setGeneralError(null);

    try {
      const data = await getOrder(orderId.trim() || 'O001', reason.trim());
      setOrder(data);
    } catch (err: any) {
      setOrder(null);
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND')
      ) {
        setRevokedError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (err?.status === 404 || err?.code === 'NOT_FOUND') {
        setNotFoundError('주문 정보를 찾을 수 없습니다.');
      } else {
        setGeneralError(err?.message || '조회 중 오류가 발생했습니다.');
