import { configureToiFetch, toiFetch } from '@toi/fetch';

export interface Refund {
  id: string;
  orderId: string;
  amount: number;
  status: string;
  reason: string;
}

type HostConfig = Parameters<typeof configureToiFetch>[0];

let isConfigured = false;
export function initFetch() {
  if (isConfigured) return;
  const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
  if (!hostConfig) {
    throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
  }
  configureToiFetch(hostConfig);
  isConfigured = true;
}

initFetch();

export class AccessRevokedError extends Error {
  code = 'PROJECT_NOT_FOUND';
  status = 404;
  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

export async function listRefunds(reason: string): Promise<Refund[]> {
  initFetch();
  let response: Response;
  try {
    response = await toiFetch('refunds', '/refunds', { reason });
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      String(err?.message).includes('PROJECT_NOT_FOUND')
    ) {
      throw new AccessRevokedError();
    }
    throw err;
  }

  if (!response.ok) {
    let errBody: any = null;
    try {
      errBody = await response.json();
    } catch {
      // response body might not be JSON
    }

    if (
      response.status === 404 &&
      (errBody?.code === 'PROJECT_NOT_FOUND' ||
        errBody?.error === 'PROJECT_NOT_FOUND' ||
        errBody?.message === 'PROJECT_NOT_FOUND')
    ) {
      throw new AccessRevokedError();
    }

    if (response.status === 404) {
      // Only resource 404 errors with a different code may show no results.
      return [];
    }

    throw new Error(errBody?.message || `요청 실패 (${response.status})`);
  }

  const data = await response.json();
  if (Array.isArray(data)) {
    return data;
  }
  if (Array.isArray(data?.items)) {
    return data.items;
  }
  return [];
}

import { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listRefunds, Refund, AccessRevokedError } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [refunds, setRefunds] = useState<Refund[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const data = await listRefunds(reason.trim());
      setRefunds(data);
      setHasSearched(true);
    } catch (err: any) {
      if (
        err instanceof AccessRevokedError ||
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND'
      ) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setError(err?.message || '환불 목록을 불러오는 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  const columns = [
    { key: 'id', header: 'id', title: 'id', label: 'id', dataIndex: 'id' },
    { key: 'orderId', header: 'orderId', title: 'orderId', label: 'orderId', dataIndex: 'orderId' },
    { key: 'amount', header: 'amount', title: 'amount', label: 'amount', dataIndex: 'amount' },
    { key: 'status', header: 'status', title: 'status', label: 'status', dataIndex: 'status' },
    { key: 'reason', header: 'reason', title: 'reason', label: 'reason', dataIndex: 'reason' },
  ];

  return (
    <main style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '20px' }}>환불 목록</h1>

      <section style={{ display: 'flex', gap: '12px', alignItems: 'flex-start', marginBottom: '24px' }}>
        <div style={{ flex: 1 }}>
          <TextField
            label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e: any) => {
              const val = typeof e === 'string' ? e : (e?.target?.value ?? '');
              setReason(val);
            }}
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ color: '#dc2626', fontSize: '13px', marginTop: '4px' }}>
              조회 사유를 5자 이상 입력해 주세요.
            </p>
          )}
        </div>
        <div style={{ marginTop: '24px' }}>
          <Button onClick={handleSearch} disabled={!isReasonValid || loading}>
            {loading ? '조회 중...' : '조회'}
          </Button>
        </div>
      </section>

      {error ? (
        <div
          role="alert"
          style={{
            padding: '16px',
            marginBottom: '16px',
            backgroundColor: '#fee2e2',
            color: '#b91c1c',
            borderRadius: '6px',
            fontSize: '14px',
          }}
        >
          {error}
        </div>
      ) : (
        <Table columns={columns} data={refunds} style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#f9fafb' }}>
              <th style={{ textAlign: 'left', padding: '12px 16px', borderBottom: '2px solid #e5e7eb' }}>id</th>
              <th style={{ textAlign: 'left', padding: '12px 16px', borderBottom: '2px solid #e5e7eb' }}>orderId</th>
              <th style={{ textAlign: 'left', padding: '12px 16px', borderBottom: '2px solid #e5e7eb' }}>amount</th>
              <th style={{ textAlign: 'left', padding: '12px 16px', borderBottom: '2px solid #e5e7eb' }}>status</th>
              <th style={{ textAlign: 'left', padding: '12px 16px', borderBottom: '2px solid #e5e7eb' }}>reason</th>
            </tr>
          </thead>
          <tbody>
            {refunds.length === 0 ? (
              <tr>
                <td colSpan={5} style={{ textAlign: 'center', padding: '32px', color: '#6b7280' }}>
                  {hasSearched ? '조회된 환불 내역이 없습니다.' : '조회 사유를 5자 이상 입력하고 조회 버튼을 눌러주세요.'}
                </td>
              </tr>
            ) : (
              refunds.map((refund) => (
                <tr key={refund.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
                  <td style={{ padding: '12px 16px' }}>{refund.id}</td>
                  <td style={{ padding: '12px 16px' }}>{refund.orderId}</td>
                  <td style={{ padding: '12px 16px' }}>{refund.amount}</td>
                  <td style={{ padding: '12px 16px' }}>
                    <Badge>{refund.status}</Badge>
                  </td>
                  <td style={{ padding: '12px 16px' }}>{refund.reason}</td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      )}
    </main>
  );
}

