import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Refund {
  id: string;
  orderId?: string;
  amount: number;
  status: string;
  reason?: string;
}

export class ToiAccessRevokedError extends Error {
  readonly code = 'PROJECT_NOT_FOUND';
  readonly status = 404;
  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

export class ResourceNotFoundError extends Error {
  readonly code = 'RESOURCE_NOT_FOUND';
  readonly status = 404;
  constructor(message = '조회 결과가 없습니다.') {
    super(message);
    this.name = 'ResourceNotFoundError';
  }
}

async function handleResponse<T>(response: Response): Promise<T> {
  if (!response.ok) {
    let errBody: any = null;
    try {
      errBody = await response.clone().json();
    } catch {
      // ignore
    }

    if (response.status === 404) {
      if (errBody?.code === 'PROJECT_NOT_FOUND') {
        throw new ToiAccessRevokedError();
      }
      throw new ResourceNotFoundError(errBody?.message || '조회 결과가 없습니다.');
    }

    throw new Error(errBody?.message || `요청 실패 (${response.status})`);
  }

  return response.json();
}

export async function getRefund(id: string, reason: string): Promise<Refund> {
  try {
    const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
      reason,
    });
    return await handleResponse<Refund>(response);
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND')
    ) {
      throw new ToiAccessRevokedError();
    }
    throw err;
  }
}

export async function approveRefund(id: string, reason: string): Promise<Refund> {
  try {
    const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
      method: 'PATCH',
      reason,
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ status: 'approved' }),
    });
    return await handleResponse<Refund>(response);
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND')
    ) {
      throw new ToiAccessRevokedError();
    }
    throw err;
  }
}

export const getRecord = getRefund;
export const updateStatus = async (
  id: string,
  status: 'requested' | 'approved' | 'rejected',
  reason: string
): Promise<Refund> => {
  const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });
  return handleResponse<Refund>(response);
};

import { useState } from 'react';
import { Button, TextField, Badge } from '@toi/tds';
import { getRefund, approveRefund, Refund, ToiAccessRevokedError, ResourceNotFoundError } from './api';

export default function App() {
  const [refundId, setRefundId] = useState('R001');
  const [reason, setReason] = useState('');
  const [refund, setRefund] = useState<Refund | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isApproving, setIsApproving] = useState(false);
  const [accessRevokedError, setAccessRevokedError] = useState<string | null>(null);
  const [resourceNotFoundError, setResourceNotFoundError] = useState<string | null>(null);
  const [generalError, setGeneralError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const clearErrors = () => {
    setAccessRevokedError(null);
    setResourceNotFoundError(null);
    setGeneralError(null);
    setSuccessMessage(null);
  };

  const handleSearch = async () => {
    if (!isReasonValid) return;
    setIsLoading(true);
    clearErrors();
    try {
      const data = await getRefund(refundId.trim(), reason.trim());
      setRefund(data);
    } catch (err: any) {
      setRefund(null);
      if (
        err instanceof ToiAccessRevokedError ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        err?.name === 'ToiAccessRevokedError' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND')
      ) {
        setAccessRevokedError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (
        err instanceof ResourceNotFoundError ||
        err?.name === 'ResourceNotFoundError' ||
        (err?.status === 404 && err?.code !== 'PROJECT_NOT_FOUND')
      ) {
        setResourceNotFoundError('조회 결과가 없습니다.');
      } else {
        setGeneralError(err?.message || '환불 정보를 불러오는 중 오류가 발생했습니다.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleApprove = async () => {
    if (!isReasonValid) return;
    setIsApproving(true);
    clearErrors();
    const targetId = refund ? refund.id : refundId.trim();
    try {
      const updated = await approveRefund(targetId, reason.trim());
      setRefund(updated);
      setSuccessMessage('환불이 승인되었습니다.');
    } catch (err: any) {
      if (
        err instanceof ToiAccessRevokedError ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        err?.name === 'ToiAccessRevokedError' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND')
      ) {
        setAccessRevokedError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (
        err instanceof ResourceNotFoundError ||
        err?.name === 'ResourceNotFoundError' ||
        (err?.status === 404 && err?.code !== 'PROJECT_NOT_FOUND')
      ) {
        setResourceNotFoundError('환불 대상을 찾을 수 없습니다.');
      } else {
        setGeneralError(err?.message || '환불 승인 처리 중 오류가 발생했습니다.');
      }
    } finally {
      setIsApproving(false);
    }
  };

  return (
    <main style={{ maxWidth: 680, margin: '40px auto', padding: '0 20px', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <header style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 24, fontWeight: 700, margin: '0 0 8px 0', color: '#191f28' }}>환불 상태 관리</h1>
        <p style={{ margin: 0, fontSize: 14, color: '#6b7684' }}>환불 내역을 조회하고 승인 상태로 변경합니다.</p>
      </header>

      <section
        style={{
          backgroundColor: '#f9fafb',
          padding: 24,
          borderRadius: 12,
          marginBottom: 24,
          border: '1px solid #e5e8eb',
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div>
            <label htmlFor="refund-id-input" style={{ display: 'block', fontSize: 14, fontWeight: 600, color: '#333d4b', marginBottom: 6 }}>
              환불 ID
            </label>
            <TextField
              id="refund-id-input"
              label="환불 ID"
              aria-label="환불 ID"
              value={refundId}
              onChange={(e: any) => {
                const val = typeof e === 'string' ? e : e?.target?.value ?? '';
                setRefundId(val);
              }}
              placeholder="R001"
            />
          </div>

          <div>
            <label htmlFor="reason-input" style={{ display: 'block', fontSize: 14, fontWeight: 600, color: '#333d4b', marginBottom: 6 }}>
              사유 <span style={{ color: '#e11d48' }}>*</span>
            </label>
            <TextField
              id="reason-input"
              label="사유"
              aria-label="사유"
              name="reason"
              value={reason}
              onChange={(e: any) => {
                const val = typeof e === 'string' ? e : e?.target?.value ?? '';
                setReason(val);
              }}
              placeholder="사유를 5자 이상 입력하세요"
            />
            {reason.length > 0 && !isReasonValid && (
              <p style={{ margin: '6px 0 0 0', fontSize: 13, color: '#e11d48' }}>
                사유는 5자 이상 입력해야 합니다. (현재 {reason.trim().length}자)
              </p>
            )}
          </div>

          <div style={{ display: 'flex', gap: 12, marginTop: 4 }}>
            <Button
              type="button"
              onClick={handleSearch}
              disabled={isLoading || !isReasonValid}
            >
              {isLoading ? '조회 중...' : '조회'}
            </Button>
            <Button
              type="button"
              onClick={handleApprove}
              disabled={isApproving || !isReasonValid}
            >
              {isApproving ? '승인 처리 중...' : '승인'}
            </Button>
          </div>
        </div>
      </section>

      {accessRevokedError && (
        <div
          role="alert"
          style={{
            padding: 16,
            borderRadius: 8,
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            color: '#b91c1c',
            marginBottom: 20,
            fontSize: 14,
            fontWeight: 500,
          }}
        >
          {accessRevokedError}
        </div>
      )}

      {resourceNotFoundError && !accessRevokedError && (
        <div
          role="status"
          style={{
            padding: 16,
            borderRadius: 8,
            backgroundColor: '#f3f4f6',
            border: '1px solid #e5e7eb',
            color: '#4b5563',
            marginBottom: 20,
            fontSize: 14,
          }}
        >
          {resourceNotFoundError}
        </div>
      )}

      {generalError && (
        <div
          role="alert"
          style={{
            padding: 16,
            borderRadius: 8,
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            color: '#b91c1c',
            marginBottom: 20,
            fontSize: 14,
          }}
        >
          {generalError}
        </div>
      )}

      {successMessage && (
        <div
          role="status"
          style={{
            padding: 16,
            borderRadius: 8,
            backgroundColor: '#ecfdf5',
            border: '1px solid #a7f3d0',
            color: '#065f46',
            marginBottom: 20,
            fontSize: 14,
            fontWeight: 500,
          }}
        >
          {successMessage}
        </div>
      )}

      {refund && (
        <section
          data-testid="refund-details"
          style={{
            border: '1px solid #e5e8eb',
            borderRadius: 12,
            padding: 24,
            backgroundColor: '#ffffff',
            boxShadow: '0 1px 3px rgba(0, 0, 0, 0.04)',
          }}
        >
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, borderBottom: '1px solid #f2f4f6', paddingBottom: 12 }}>
            <h2 style={{ margin: 0, fontSize: 18, fontWeight: 600, color: '#191f28' }}>환불 상세 내역</h2>
            <Badge>{refund.status}</Badge>
          </div>

          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <tbody>
              <tr style={{ borderBottom: '1px solid #f2f4f6' }}>
                <th style={{ textAlign: 'left', padding: '12px 8px', color: '#6b7684', fontWeight: 500, width: 120 }}>id</th>
                <td style={{ padding: '12px 8px', fontWeight: 600, color: '#191f28' }} data-testid="refund-id">{refund.id}</td>
              </tr>
              <tr style={{ borderBottom: '1px solid #f2f4f6' }}>
                <th style={{ textAlign: 'left', padding: '12px 8px', color: '#6b7684', fontWeight: 500 }}>amount</th>
                <td style={{ padding: '12px 8px', fontWeight: 600, color: '#191f28' }} data-testid="refund-amount">{refund.amount}</td>
              </tr>
              <tr style={{ borderBottom: '1px solid #f2f4f6' }}>
                <th style={{ textAlign: 'left', padding: '12px 8px', color: '#6b7684', fontWeight: 500 }}>status</th>
                <td style={{ padding: '12px 8px', fontWeight: 600, color: '#191f28' }} data-testid="refund-status">{refund.status}</td>
              </tr>
              {refund.orderId != null && (
                <tr style={{ borderBottom: '1px solid #f2f4f6' }}>
                  <th style={{ textAlign: 'left', padding: '12px 8px', color: '#6b7684', fontWeight: 500 }}>orderId</th>
                  <td style={{ padding: '12px 8px', color: '#333d4b' }}>{refund.orderId}</td>
                </tr>
              )}
              {refund.reason != null && (
                <tr>
                  <th style={{ textAlign: 'left', padding: '12px 8px', color: '#6b7684', fontWeight: 500 }}>reason</th>
                  <td style={{ padding: '12px 8px', color: '#333d4b' }}>{refund.reason}</td>
                </tr>
              )}
            </tbody>
          </table>
        </section>
      )}
    </main>
  );
}

